            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _event(dec, k) {
            var c = this.C;
            var self = this;
            var a = {};
            var j;
            for (j = 0; j < this.KEYS.length; j++) { a[this.KEYS[j]] = this._active(dec, k, this.KEYS[j]); }
            var pl = this.PLANT[a.plantilla1];
            var ca = this.CANAL[a.canal1];
            var pv = this.PROV[a.proveedores2];
            var te = this.TECH[a.tecnologia2];
            var cg = this.CARGO[a.cargos3];
            var fi = this.FIN[a.financia3];
            var ic = this.INC[a.incentivo4];
            var fo = this.FOCO[a.foco4];
            var agents = pl[0];
            var d = c.E0 * ca[0] * pl[3] * te[2] * pv[2] * cg[1] * fi[3];
            var autumn = (k >= 4) ? c.AUTUMN : 1.0;
            var dh = d * c.FH;
            var dq = d * c.FQ * ic[3] * fo[0] * autumn;
            var cap = agents * c.CAPA * pl[2] * te[1] * pv[4];
            var eh = Math.min(dh, cap * c.FH);
            var eq = Math.min(dq, cap * c.FQ);
            var exp = eh + eq;
            var vh = c.V0 * pl[4] * ca[4];
            var vq = vh * fo[1];
            var sh = eh * vh;
            var sq = eq * vq;
            var sales = sh + sq;
            var cut = (k >= 2) ? c.CUT * (1.0 - pv[1]) : 0.0;
            var r = c.COM0 + pv[0] - cut + te[3] + cg[2] + fi[2];
            var rq = r + fo[3] + ic[4];
            var keep = 1.0 - ca[3];
            var comh = sh * r * keep;
            var comq = sq * rq * keep;
            var fees = eh * cg[0] + eq * (cg[0] + fo[2]);
            var gross = comh + comq + fees;
            var mq = comq + eq * (cg[0] + fo[2]);
            var inc = ic[0] * mq + ic[1] * sq + ic[2] * agents;
            var staff = agents * pl[1];
            var costs = staff + ca[2] + ca[1] + te[0] + pv[5] + fi[1] + inc + fo[4] + c.FIXED;
            var profit = gross - costs;
            var share = exp / c.MKT;
            var wc = sh * c.WCR * (1.0 - pv[3]);
            var cash = c.CASH0 + c.CASH_P * profit + fi[0] - wc;
            var mrate = gross / sales;
            var hard = 0;
            this.HARD.forEach(function(h) { if (a[h[0]] === h[1] && k >= self.ROUND_OF[h[0]]) { hard += 1; } });
            return { k: k, a: a, profit: profit, cuota: share, caja: cash, margen: mrate, exp: exp, eh: eh, eq: eq,
                     cap: cap, sales: sales, com: comh + comq, fees: fees, gross: gross, inc: inc, costs: costs,
                     vh: vh, vq: vq, hard: hard };
        }

        _components(r) {
            var c = this.C;
            return [this._clamp((r.profit - c.B_LO) / (c.B_HI - c.B_LO), 0, 1),
                    this._clamp((r.cuota - c.O_LO) / (c.O_HI - c.O_LO), 0, 1),
                    this._clamp((r.caja - c.C_LO) / (c.C_HI - c.C_LO), 0, 1),
                    this._clamp((r.margen - c.R_LO) / (c.R_HI - c.R_LO), 0, 1)];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_B, c.W_O, c.W_C, c.W_R];
            var tw = 0, num = 0, i;
            for (i = 0; i < 4; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.ROUND_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'en') ? ',' : '.';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _r1(x) {
            return this._jsround(x * 10.0) / 10.0;
        }

        _fmtPct1(n) {
            return this._fmtDec(n) + ((this._lang() === 'en') ? '%' : ' %');
        }

        _fmtMoney(n) {
            var v = Math.round(n);
            var body = this._fmtInt(Math.abs(v));
            if (this._lang() === 'en') { return (v < 0 ? '-' : '') + '€' + body; }
            return (v < 0 ? '-' : '') + body + ' €';
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var mH = ds.profitHistory || [];
            var oH = ds.cuotaHistory || [];
            var cH = ds.cajaHistory || [];
            var rH = ds.margenHistory || [];
            var vH = ds.expHistory || [];
            var n = mH.length;
            this._set('profitDisplay', n ? this._fmtMoney(mH[n - 1]) : '-');
            this._set('cuotaDisplay', n ? this._fmtPct1(oH[n - 1]) : '-');
            this._set('cajaDisplay', n ? this._fmtMoney(cH[n - 1]) : '-');
            this._set('margenDisplay', n ? this._fmtPct1(rH[n - 1]) : '-');
            this._set('expDisplay', n ? this._fmtInt(vH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var pfx = { plantilla1: 'pl', canal1: 'ca', proveedores2: 'pv', tecnologia2: 'te', cargos3: 'cg', financia3: 'fi', incentivo4: 'ic', foco4: 'fo' };
            var opts = {
                plantilla1: ['especialistas', 'mantener', 'recortar', 'ampliar'],
                canal1: ['omnicanal', 'oficina', 'online', 'ota'],
                proveedores2: ['preferentes', 'todos', 'exclusiva', 'netas'],
                tecnologia2: ['midoffice', 'nada', 'web', 'gds'],
                cargos3: ['cargo', 'gratis', 'descuento', 'alto'],
                financia3: ['poliza', 'aplazar', 'socios', 'sin_garantia'],
                incentivo4: ['margen', 'fijo', 'ventas', 'bono'],
                foco4: ['empresas', 'todo', 'escapadas', 'cruceros']
            };
            var keys = {
                fb_pl_especialistas: 1, fb_pl_mantener: 1, fb_pl_recortar: 1, fb_pl_ampliar: 1,
                fb_ca_omnicanal: 1, fb_ca_oficina: 1, fb_ca_online: 1, fb_ca_ota: 1,
                fb_pv_preferentes: 1, fb_pv_todos: 1, fb_pv_exclusiva: 1, fb_pv_netas: 1,
                fb_te_midoffice: 1, fb_te_nada: 1, fb_te_web: 1, fb_te_gds: 1,
                fb_cg_cargo: 1, fb_cg_gratis: 1, fb_cg_descuento: 1, fb_cg_alto: 1,
                fb_fi_poliza: 1, fb_fi_aplazar: 1, fb_fi_socios: 1, fb_fi_sin_garantia: 1,
                fb_ic_margen: 1, fb_ic_fijo: 1, fb_ic_ventas: 1, fb_ic_bono: 1,
                fb_fo_empresas: 1, fb_fo_todo: 1, fb_fo_escapadas: 1, fb_fo_cruceros: 1
            };
            if (!opts[g] || opts[g].indexOf(v) < 0) { return 'fb_next'; }
            var key = 'fb_' + pfx[g] + '_' + v;
            return keys[key] ? key : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._event(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

