                { key: 'results.cuota', label: 'Market share', i18nKey: 'col_cuota', formatter: pct },
                { key: 'results.caja', label: 'Cash at the low point', i18nKey: 'col_caja', formatter: money },
                { key: 'results.margen', label: 'Gross margin on sales', i18nKey: 'col_margen', formatter: pct },
                { key: 'results.exp', label: 'Booking files', i18nKey: 'col_exp', formatter: count },
