                + '<div class="ej2714-cm-kpi">' + this._t('cm_kpi_margen') + ' <strong>' + this._fmtPct1(s.margen || 0) + '</strong></div>'
                + '<div class="ej2714-cm-kpi">' + this._t('cm_kpi_exp') + ' <strong>' + this._fmtInt(s.exp || 0) + '</strong></div>'
                + '</div>'
                + '<div class="ej2714-cm-debrief">' + this._t('cm_debrief') + '</div>'
